/* events.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function bindEvents(P) {


  /* ---------- events ---------- */

  P.$("playerPlay").addEventListener("click", () => {
    if (!P.state.current) {
      if (P.state.context?.tracks?.length) P.selectByIndex(0);
      return;
    }
    P.toggle();
  });
  P.$("playerPrev").addEventListener("click", P.previous);
  P.$("playerNext").addEventListener("click", () => P.next(true));
  P.$("playerClose").addEventListener("click", P.stop);

  P.seek.addEventListener("input", () => {
    P.introUserSeeked = true;
    P.setTime((Number(P.seek.value) / 1000) * (P.audio.duration || 0));
  });

  P.volume.addEventListener("input", () => {
    const value = Math.min(1, Math.max(0, Number(P.volume.value)));
    P.state.volume = value;
    P.audio.volume = value;
    P.audio.muted = value === 0;
    P.state.muted = P.audio.muted;
    // If user changes volume during fade-in, don't let fade override it later.
    if (P.incomingFadeActive) {
      P.incomingFadeToken++;
      P.incomingFadeActive = 0;
      if (P.mainGainNode) {
        try { const t = P.audioContext.currentTime; P.mainGainNode.gain.cancelScheduledValues(t); P.mainGainNode.gain.setValueAtTime(1, t); } catch {}
      }
    }
    try { P.howl?.volume(value); P.howl?.mute(P.audio.muted); } catch {}
    P.updateMuteState();
    P.saveState();
  });

  P.$("playerMute").addEventListener("click", () => {
    P.audio.muted = !P.audio.muted;
    P.state.muted = P.audio.muted;
    try { P.howl?.mute(P.audio.muted); } catch {}
    P.updateMuteState();
    P.saveState();
  });

  P.$("playerShuffle").addEventListener("click", () => {
    P.state.shuffle = !P.state.shuffle;
    P.shufflePick = null;
    P.applyShuffle();
    P.saveState();
    P.notify("settings");
    P.schedulePreload();
  });

  P.$("playerRepeat").addEventListener("click", () => {
    const modes = ["off", "all", "one"];
    P.state.repeat = modes[(modes.indexOf(P.state.repeat) + 1) % modes.length];
    P.applyRepeat();
    P.saveState();
    P.notify("settings");
    P.schedulePreload();
  });

  P.settingsToggle.addEventListener("click", () => {
    P.settingsPanel.hidden ? P.openSettings() : P.closeSettings();
  });
  P.$("playerSettingsClose").addEventListener("click", P.closeSettings);
  document.addEventListener("click", (ev) => {
    const target = ev.target instanceof Element ? ev.target : null;
    const button = target?.closest("[data-remix-action]");
    if (!button) return;
    const action = button.dataset.remixAction;
    if (action === "create") { P.bakeRemixNow(); return; }
    if (action === "save") {
      const format = button.closest("[data-player-settings-mount]")
        ?.querySelector("[data-player-setting='remixFormat']")?.value || P.state.remixFormat;
      P.saveRemix(format);
      return;
    }
    if (action === "load") {
      button.closest("[data-player-settings-mount]")
        ?.querySelector("[data-remix-file]")?.click();
    }
  });
  document.addEventListener("change", (ev) => {
    const input = ev.target instanceof Element ? ev.target.closest("[data-remix-file]") : null;
    if (!input || !(input instanceof HTMLInputElement)) return;
    P.loadRemixFile(input.files?.[0]);
    input.value = "";
  });
  P.queueToggle?.addEventListener("click", P.toggleQueue);
  P.$("playerQueueClose")?.addEventListener("click", P.closeQueue);
  P.$("playerQueueClear")?.addEventListener("click", P.clearQueue);
  P.queuePanel?.addEventListener("click", (ev) => {
    if (ev.target === P.queuePanel) { P.closeQueue(); return; }
    const target = ev.target instanceof Element ? ev.target : null;
    if (!target) return;
    const remove = target.closest("[data-queue-remove]");
    if (remove) { P.removeFromQueue(Number(remove.dataset.queueRemove)); return; }
    const play = target.closest("[data-queue-play]");
    if (play) P.playQueued(Number(play.dataset.queuePlay));
  });
  document.addEventListener("keydown", (ev) => {
    if (ev.key !== "Escape") return;
    if (P.settingsPanel && !P.settingsPanel.hidden) P.closeSettings();
    else if (P.queuePanel && !P.queuePanel.hidden) P.closeQueue();
  });

  document.addEventListener("click", (ev) => {
    const target = ev.target instanceof Element ? ev.target : null;
    if (!target) return;
    const share = target.closest("[data-player-share]");
    if (share) { P.shareSettings(share); return; }
    if (target.closest("#playerEqReset")) P.resetEq();
  });

  function applyFadeSetting(key, rawValue) {
    const clampFade = (value, fallback) => {
      const n = Number(value);
      return Number.isFinite(n) ? Math.min(P.CROSSFADE_MAX_MS, Math.max(P.CROSSFADE_MIN_MS, Math.round(n))) : fallback;
    };
    if (key === "fadeOutMs") P.state.fadeOutMs = clampFade(rawValue, P.DEFAULT_FADE_OUT_MS);
    if (key === "fadeInMs") P.state.fadeInMs = clampFade(rawValue, P.DEFAULT_FADE_IN_MS);
    P.syncSettingsUI();
    P.saveState();
    P.notify("settings");
  }

  document.addEventListener("change", (ev) => {
    const target = ev.target instanceof Element ? ev.target : null;
    if (!target) return;
    if (target.id === "playerEqReset") { P.resetEq(); return; }
    if (target.id === "playerEqAdd") { P.addEqFilter(); return; }
    const eqRemove = target.closest("[data-eq-remove]");
    if (eqRemove) { P.removeEqFilter(Number(eqRemove.dataset.eqRemove)); return; }

    const eqField = target.closest("[data-eq-field]");
    if (eqField) {
      const row = target.closest("[data-eq-index]");
      const index = Number(row?.dataset.eqIndex);
      const field = eqField.dataset.eqField;
      const value = eqField.type === "checkbox" ? eqField.checked : eqField.value;
      if (Number.isInteger(index) && field) P.setEqParam(index, field, value);
      return;
    }

    const input = target.closest("[data-player-setting]");
    if (!input) return;
    const key = input.dataset.playerSetting;
    if (key === "engine") P.setEngine(input.value);
    else if (key === "format") P.setFormat(input.value);
    else if (key === "playbackRate") P.setPlaybackRate(input.value);
    else if (key === "playbackMode") P.setPlaybackMode(input.value);
    else if (key === "pitchMode") P.setPitchMode(input.value);
    else if (key === "fadeOutMs" || key === "fadeInMs") P.applyFadeSetting(key, input.value);
    else if (key === "silenceDb" || key === "introMaxSec") P.applyIntroSetting(key, input.value);
    else if (key === "eqEnabled") P.setEqEnabled(input.checked);
    else if (P.FX_KINDS.some((kind) => key === `${kind}Enabled`)) P.setFxEnabled(key.replace(/Enabled$/, ""), input.checked);
    else if (key === "limiterMode") P.setLimiterMode(input.value);
    else if (key === "fxBakeDelayMs") P.applyBakeDelay(input.value);
    else if (key === "remixFormat" && P.REMIX_FORMATS.includes(input.value)) {
      P.state.remixFormat = input.value;
      P.syncSettingsUI();
      P.saveState();
      P.notify("settings");
    }
    else if (key === "limiterEnabled") {
      P.state.limiterEnabled = !!input.checked;
      P.limiterEnabled = P.state.limiterEnabled;
      P.ensureMasterOutput();
      P.wireMasterOutput();
      P.connectMainOutput();
      P.syncSettingsUI();
      P.saveState();
      P.notify("settings");
    }
    else if (key === "autoNext" || key === "rememberPosition" || key === "crossfade"
      || key === "fadeInEnabled" || key === "fadeOutEnabled" || key === "skipIntro") {
      P.state[key] = !!input.checked;
      if (key === "crossfade" && !P.state.crossfade) P.stopFades();
      if (key === "fadeOutEnabled" && !P.state.fadeOutEnabled) P.stopFades();
      if (key === "crossfade" || key === "fadeInEnabled" || key === "fadeOutEnabled") P.incomingFadeToken++;
      P.syncSettingsUI();
      P.saveState();
      P.notify("settings");
    }
  });

  document.addEventListener("input", (ev) => {
    const target = ev.target instanceof Element ? ev.target : null;
    if (!target) return;
    const eqField = target.closest("[data-eq-field]");
    if (eqField) {
      const row = target.closest("[data-eq-index]");
      const index = Number(row?.dataset.eqIndex);
      const field = eqField.dataset.eqField;
      const value = eqField.type === "checkbox" ? eqField.checked : eqField.value;
      if (Number.isInteger(index) && field) P.setEqParam(index, field, value);
      return;
    }
    const input = target.closest("[data-player-setting]");
    if (!input) return;
    const key = input.dataset.playerSetting;
    if (key === "fadeOutMs" || key === "fadeInMs") P.applyFadeSetting(key, input.value);
    else if (key === "silenceDb" || key === "introMaxSec") P.applyIntroSetting(key, input.value);
    else if (key === "fxBakeDelayMs") P.applyBakeDelay(input.value);
    else if (key === "playbackRate") P.setPlaybackRate(input.value);
    else if (P.FX_RANGES[key]) P.applyFxSetting(key, input.value);
  });

  P.audio.addEventListener("loadedmetadata", () => {
    if (P.pendingStart != null && P.pendingStart > 0) {
      try { P.audio.currentTime = P.pendingStart; } catch {}
    }
    P.pendingStart = null;
    P.updateTime();
    if (P.usesNativeProgress() && P.loadingEl && !P.loadingEl.hidden) {
      P.setLoadingProgress(Math.max(P.bufferedPercent(), 20));
    }
  });
  P.audio.addEventListener("progress", () => {
    if (P.usesNativeProgress() && P.loadingEl && !P.loadingEl.hidden) P.setLoadingProgress(P.bufferedPercent());
  });
  P.audio.addEventListener("loadeddata", () => {
    if (P.usesNativeProgress() && P.loadingEl && !P.loadingEl.hidden) {
      P.setLoadingProgress(Math.max(P.bufferedPercent(), 45));
    }
  });
  P.audio.addEventListener("canplay", () => { if (P.usesNativeProgress()) P.finishLoading(); });
  P.audio.addEventListener("playing", P.finishLoading);
  P.audio.addEventListener("timeupdate", () => { P.updateTime(); P.saveStateSoon(); });
  P.audio.addEventListener("play", P.updatePlayState);
  P.audio.addEventListener("pause", () => { P.updatePlayState(); P.saveStateSoon(); });
  P.audio.addEventListener("volumechange", P.updateMuteState);
  P.audio.addEventListener("ended", P.handleEnded);
  P.audio.addEventListener("error", () => { P.setLoading(false); });
  // A failed prefetch should not block the next attempt forever.
  P.preloadAudio?.addEventListener("error", () => { P.preloadUrl = ""; });

  document.addEventListener("keydown", (ev) => {
    const target = ev.target;
    if (target instanceof Element && target.closest("input, textarea, select, [contenteditable='true']")) return;
    if (ev.metaKey || ev.ctrlKey || ev.altKey) return;
    if (ev.code === "Space" && P.state.current) { ev.preventDefault(); P.toggle(); }
    else if (ev.key === "ArrowRight" && P.state.current) { ev.preventDefault(); P.introUserSeeked = true; P.setTime(P.audio.currentTime + 5); }
    else if (ev.key === "ArrowLeft" && P.state.current) { ev.preventDefault(); P.introUserSeeked = true; P.setTime(P.audio.currentTime - 5); }
    else if (ev.key.toLowerCase() === "m" && P.state.current) {
      P.audio.muted = !P.audio.muted;
      P.state.muted = P.audio.muted;
      try { P.howl?.mute(P.audio.muted); } catch {}
      P.updateMuteState();
      P.saveState();
    }
  });

  window.addEventListener("zqwy:languagechange", (event) => {
    P.setPlayerLanguage(event?.detail?.language);
  });

  window.addEventListener("zqwy:themechange", () => {
    const colors = P.waveformColors();
    P.drawEqCurve();
    P.drawFadeEnvelope();
    if (P.waveSurfer && typeof P.waveSurfer.setOptions === "function") {
      try {
        P.waveSurfer.setOptions({
          waveColor: colors.waveColor,
          progressColor: colors.progressColor,
          cursorColor: colors.cursorColor,
        });
      } catch {}
    }
    if (P.peaks) {
      try {
        const view = P.peaks.views.getView("zoomview");
        if (view) {
          view.setWaveformColor(colors.waveColor);
          view.setPlayedWaveformColor(colors.progressColor);
          view.setPlayheadColor?.(colors.cursorColor);
        }
      } catch {}
    }
    if (P.state.engine === "waviz" && P.waviz && !P.audio.paused) {
      try { P.waviz.stop(); P.waviz.simpleLine(colors.progressColor).catch(() => {}); } catch {}
    }
  });

  window.addEventListener("zqwy:pagechange", () => {
    P.applySharedSettings();
    P.mountSettings();
    P.updateTime();
  });

  window.addEventListener("pagehide", P.saveState);
  document.addEventListener("visibilitychange", () => { if (document.hidden) P.saveState(); });
  Object.assign(P, { applyFadeSetting });
}
